(()=>{const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;const scenes=[...document.querySelectorAll('.cinema-scene')];if(!scenes.length)return;const player=document.querySelector('.scene-player');let active=0,motion=!reduced,ticking=false;const update=()=>{const point=innerHeight*.4;let closest=Infinity;scenes.forEach((s,i)=>{const b=s.getBoundingClientRect(),dist=Math.abs(b.top-point);if(b.top<point&&b.bottom>point){active=i;closest=-1}else if(closest!==-1&&dist<closest){active=i;closest=dist}});const first=scenes[0].getBoundingClientRect(),last=scenes.at(-1).getBoundingClientRect();player.classList.toggle('is-active',first.top<innerHeight*.8&&last.bottom>100);player.querySelector('.player-number').textContent=String(active+1).padStart(2,'0');player.querySelector('.player-title').textContent=scenes[active].dataset.sceneTitle;document.querySelectorAll('.case-layout aside a[href^="#"]').forEach(a=>{if(a.hash==='#'+scenes[active].id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});player.querySelector('[data-scene-action=previous]').disabled=active===0;player.querySelector('[data-scene-action=next]').disabled=active===scenes.length-1;ticking=false};document.body.classList.toggle('cinema-motion',motion);if('IntersectionObserver'in window){const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add(e.target.classList.contains('cinema-scene')?'scene-entered':'seen');if(e.target.classList.contains('film-frame'))obs.unobserve(e.target)}}),{threshold:.05,rootMargin:'0px 0px -3% 0px'});document.querySelectorAll('.film-frame,.cinema-scene').forEach((el,i)=>{if(el.classList.contains('film-frame'))el.style.setProperty('--delay',(i%3)*70+'ms');obs.observe(el)})}player.querySelectorAll('[data-scene-action]').forEach(b=>b.addEventListener('click',()=>{const action=b.dataset.sceneAction;if(action==='motion'){motion=!motion;document.body.classList.toggle('motion-paused',!motion);b.setAttribute('aria-pressed',String(motion));b.textContent=motion?'动效开启':'动效关闭'}else{const next=Math.max(0,Math.min(scenes.length-1,active+(action==='next'?1:-1)));scenes[next].scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})}}));addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(update)}},{passive:true});update();document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{const section=b.closest('.artist-statement');section.querySelectorAll('[data-language]').forEach(button=>button.setAttribute('aria-pressed',String(button===b)));section.querySelectorAll('[data-statement]').forEach(copy=>copy.hidden=copy.dataset.statement!==b.dataset.language)}));})();
